import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CRFziyHp.js";const g=JSON.parse('{"title":"文件存储","description":"","frontmatter":{},"headers":[],"relativePath":"features/storage.md","filePath":"features/storage.md","lastUpdated":1785013113000}'),l={name:"features/storage.md"};function i(d,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="文件存储" tabindex="-1">文件存储 <a class="header-anchor" href="#文件存储" aria-label="Permalink to &quot;文件存储&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置用户上传的图片、视频等文件的保存位置，支持服务器本地或主流云对象存储。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>若选云存储：已在对应云厂商创建 Bucket，并获取访问密钥。</li><li>站点 <strong>系统配置</strong> 读写权限。</li><li>视频水印功能额外要求服务器安装 <code>ffmpeg</code>（见系统配置 <strong>视频水印</strong> Tab）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>系统设置 → 系统配置 → 文件存储</strong> Tab</p><h3 id="本地存储-local" tabindex="-1">本地存储（local） <a class="header-anchor" href="#本地存储-local" aria-label="Permalink to &quot;本地存储（local）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td>适用</td><td>小规模部署、内网测试</td></tr><tr><td>注意</td><td>文件保存在应用服务器磁盘，需自行备份与扩容</td></tr><tr><td>访问</td><td>通过站点域名下的静态路径访问，依赖反向代理配置</td></tr></tbody></table><p>选择 <strong>local</strong> 后保存即可；确保服务器磁盘空间充足。</p><h3 id="云存储" tabindex="-1">云存储 <a class="header-anchor" href="#云存储" aria-label="Permalink to &quot;云存储&quot;">​</a></h3><p>支持 <strong>腾讯云 COS</strong>、<strong>阿里云 OSS</strong>、<strong>七牛云</strong> 等（以页面实际选项为准）。</p><table tabindex="0"><thead><tr><th>通常需填写</th><th>说明</th></tr></thead><tbody><tr><td>存储类型</td><td>选择对应云厂商</td></tr><tr><td>AccessKey / SecretKey</td><td>云账号 API 密钥</td></tr><tr><td>Bucket 名称</td><td>存储桶</td></tr><tr><td>地域 / Endpoint</td><td>与 Bucket 所在区域一致</td></tr><tr><td>自定义域名（可选）</td><td>CDN 加速域名</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>页面若提供「本地备份」选项，可在云存储为主的同时保留一份本地副本，便于迁移；按实际磁盘情况决定是否开启。</p></div><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>文件存储为 <strong>全站统一</strong> 配置，不按区域区分。各区域可在 <strong>笔记配置</strong>、<strong>用户配置</strong> 中限制上传格式与大小，但物理存储位置共用同一套参数。</p><p>相关菜单：</p><ul><li><strong>系统设置 → 系统配置 → 功能与上传</strong>：全站允许的后缀、单文件大小上限</li><li><strong>区域管理 → 笔记配置</strong>：笔记是否允许图片/视频等</li></ul><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在客户端发布带图笔记或更换头像，上传进度正常且图片可访问。</li><li><strong>系统设置 → 文件管理</strong> 中能看到新上传记录（如有该菜单权限）。</li><li>若使用云存储：登录云控制台，对应 Bucket 中出现新对象。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>上传失败或 413</strong></p><ul><li>检查 <strong>功能与上传</strong> 中大小限制与 Nginx <code>client_max_body_size</code> 是否一致。</li><li>云存储密钥、Bucket 名称、地域是否匹配。</li></ul><p><strong>图片链接打不开</strong></p><ul><li>local 模式：确认静态文件目录已挂载并可公网访问。</li><li>云模式：检查 Bucket 读权限、CDN 域名是否 HTTPS 且未过期。</li></ul><p><strong>切换存储方式后旧图失效</strong></p><ul><li>历史 URL 仍指向旧位置；迁移需运维协助批量同步文件，或保留旧存储只读一段时间。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/system-settings">系统配置总览</a></li><li><a href="/features/circle-note">圈子与笔记</a></li></ul>',29)])])}const p=a(l,[["render",i]]);export{g as __pageData,p as default};
